import anndata as ad
m=pd.read_csv(R/'01_scope/reference_scope_manifest.tsv.gz',sep='\t',low_memory=False);q=m[m.included_in_this_run];labels=json.loads((R/'02_inputs/labels.json').read_text());rows=[]
