check('old reference cells preserved in audit',len(m)==300033 and m.cell_id.is_unique);check('scoped union',len(q)==281851 and q.new_reference_label.nunique()==31);check('excluded identities missing',m.loc[~m.included_in_this_run,'frozen_cluster'].isna().all());check('excluded reason',m.loc[~m.included_in_this_run,'exclusion_reason'].eq('outside_frozen_discovery_scope').all());check('no source mapping missing',q[['source_group','split']].notna().all().all());check('source groups mutually exclusive',q.groupby('source_group').split.nunique().max()==1);check('K32 exact integrity',set(q.loc[q.new_reference_label=='Epi_K32','cell_id'])==set(m.loc[m.K32.eq(True),'cell_id']))
