 O=R/'04_pseudospots'/part;mem=pd.read_csv(O/'cell_membership_RNA.tsv.gz',sep='\t');truth=pd.read_csv(O/'truth_counts.tsv.gz',sep='\t').set_index('pseudospot_id');meta=pd.read_csv(O/'manifest.tsv.gz',sep='\t').set_index('pseudospot_id');a=ad.read_h5ad(O/'counts.h5ad',backed='r');check(part+' cell source isolation',set(mem.cell_id)<=set(q.loc[q.split==part,'cell_id']));check(part+' no repeats in spot',not mem.duplicated(['pseudospot_id','cell_id']).any());check(part+' source within spot',mem.merge(q[['cell_id','sample']],on='cell_id',validate='many_to_one').groupby('pseudospot_id')['sample'].nunique().max()==1);check(part+' total count truth',truth[labels].sum(1).eq(20).all());actual=pd.crosstab(mem.pseudospot_id,mem.subtype).reindex(index=truth.index,columns=labels,fill_value=0);check(part+' truth reconstructed from members',np.array_equal(actual,truth[labels]));check(part+' matched spot order',list(a.obs_names)==list(meta.index));check(part+' no scenario/true-count covariates',set(a.obs.columns)=={'sample'});check(part+' integer sparse counts',a.X[0:100].data.dtype.kind in 'iu');check(part+' RNA totals consistent',np.array_equal(mem.groupby('pseudospot_id').post_shared_UMI.sum().reindex(meta.index),meta.post_shared_UMI));check(part+' RNA zeros retain cell truth',(meta.loc[meta.K32_shared_RNA_zero,'N_K32']>0).all());truth[labels].div(20).to_csv(O/'truth_proportions.tsv.gz',sep='\t');a.file.close()
